(function () {
// Zusatzfälle nach Klausurgewichtung, je 6 Antworten
const W=(window.WPRK_LONG=window.WPRK_LONG||[]);
const L=[{"topic": "del", "sv": "Radfahrer R fährt fahrlässig auf dem Gehweg und stößt Fußgängerin F um. F bricht sich das Handgelenk, ihre Brille geht kaputt, und sie kann zwei Wochen nicht arbeiten.", "q": "Was kann F von R verlangen?", "c": 0, "o": [["Behandlungskosten, Brille, Verdienstausfall und Schmerzensgeld (§§ 823 I, 253 II).", "Richtig. Körper- und Eigentumsverletzung, voller Schadensersatz. (§§ 823 I, 249, 252, 253 II)"], ["Nur die Brille, weil Körperschäden nur bei Vorsatz ersetzt werden.", "Falsch. Fahrlässigkeit genügt für jedes Rechtsgut des § 823 I."], ["Behandlungskosten und Brille, aber kein Schmerzensgeld, weil R nicht vorsätzlich handelte.", "Falsch. § 253 II setzt keinen Vorsatz voraus."], ["Nur den Verdienstausfall, weil das Vermögen das wichtigste Rechtsgut ist.", "Falsch. Das Vermögen ist nicht einmal Rechtsgut des § 823 I; der Verdienstausfall ist Folgeschaden."], ["Nichts, weil zwischen F und R kein Vertrag besteht.", "Falsch. § 823 I setzt keinen Vertrag voraus."], ["Alles, aber nur, wenn R wegen fahrlässiger Körperverletzung bestraft wird.", "Falsch. Eine Bestrafung ist keine Voraussetzung."]], "id": "P2-del-0"}, {"topic": "del", "sv": "Bauunternehmer B beschädigt bei Erdarbeiten fahrlässig ein Stromkabel, das dem Energieversorger gehört. Der Bäckerei S fällt dadurch sechs Stunden der Strom aus; sie kann nicht backen und verliert 1.200 € Umsatz. Ihre Maschinen bleiben unbeschädigt.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 4, "o": [["S hat einen Anspruch aus § 823 I wegen Verletzung ihres Eigentums an den Maschinen.", "Falsch. Die Maschinen sind nicht beschädigt; die bloße Nutzungsstörung von Stunden genügt nicht."], ["S hat einen Anspruch aus dem Recht am eingerichteten und ausgeübten Gewerbebetrieb.", "Falsch. Es fehlt am betriebsbezogenen Eingriff."], ["S hat einen Anspruch aus Vertrag, weil der Energieversorger B beauftragt hat.", "Falsch. S ist nicht in den Schutzbereich des Bauvertrags einbezogen."], ["S hat einen Anspruch aus § 831, weil B für seine Arbeiter haftet.", "Falsch. § 831 setzt eine widerrechtliche Rechtsgutsverletzung bei S voraus."], ["S hat keinen Anspruch, weil es ein reiner Vermögensschaden ist.", "Richtig. Reine Vermögensschäden sind über § 823 I nicht ersatzfähig."], ["S hat einen Anspruch aus § 826, weil B fahrlässig gehandelt hat.", "Falsch. § 826 verlangt Vorsatz und Sittenwidrigkeit."]], "id": "P2-del-1"}, {"topic": "del", "sv": "Händler H verkauft einem Kunden wissentlich ein gefälschtes Markenparfum als echt; der Kunde zahlt 120 €. Abgedruckt ist § 263 StGB (Betrug).", "q": "Welche deliktische Anspruchsgrundlage greift?", "c": 2, "o": [["§ 823 I, weil der Kunde in seinem Eigentum an den 120 € verletzt ist.", "Falsch. Er hat das Geld freiwillig übereignet; es geht um das Vermögen."], ["Keine, weil das Vermögen deliktisch nicht geschützt ist.", "Falsch. § 823 II und § 826 schützen auch das Vermögen."], ["§ 823 II i. V. m. § 263 StGB, weil § 263 StGB ein Schutzgesetz ist.", "Richtig. Schutzgesetz; daneben § 826."], ["§ 831, weil H als Geschäftsherr haftet.", "Falsch. H hat selbst gehandelt."], ["§ 833, weil H für gefährliche Produkte haftet.", "Falsch. § 833 betrifft Tiere."], ["Nur § 812, weil Delikt bei Verträgen ausgeschlossen ist.", "Falsch. Vertragliche und deliktische Ansprüche bestehen nebeneinander."]], "id": "P2-del-2"}, {"topic": "del", "sv": "Der 9-jährige Tim wirft im Garten mit einem Ball und zerbricht dabei absichtlich das Fenster des Nachbarn N, weil er sich über ihn ärgert. Er wusste, dass das verboten ist und Schaden anrichtet.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 3, "o": [["Tim haftet nicht, weil Kinder unter zehn Jahren nie haften.", "Falsch. § 828 II betrifft nur den Straßenverkehr; sonst gilt § 828 III."], ["Tim haftet nicht, weil er noch nicht volljährig ist.", "Falsch. Deliktsfähigkeit beginnt ab sieben Jahren (§ 828 III)."], ["Nur die Eltern haften, Tim selbst nie.", "Falsch. Tim kann selbst haften; die Eltern nur bei Aufsichtspflichtverletzung (§ 832)."], ["Tim haftet selbst, weil er einsichtsfähig war (§ 828 III).", "Richtig. Zwischen 7 und 18: Haftung bei Einsichtsfähigkeit."], ["Tim haftet nur, wenn die Eltern zustimmen.", "Falsch. Eine Zustimmung ist für Delikt ohne Bedeutung."], ["Tim haftet nur aus § 829 nach Billigkeit.", "Falsch. § 829 greift nur, wenn er sonst nicht verantwortlich wäre."]], "id": "P2-del-3"}, {"topic": "del", "sv": "Die 6-jährige Mia spielt unbeaufsichtigt an einer Hauptstraße, weil ihr Vater V auf dem Handy surft. Sie zerkratzt mit einem Stein einen parkenden Wagen.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 1, "o": [["Mia haftet selbst aus § 823 I, weil sie den Wagen beschädigt hat.", "Falsch. Sie ist unter sieben Jahre alt (§ 828 I)."], ["V haftet aus § 832, weil er seine Aufsichtspflicht verletzt hat.", "Richtig. Vermutete Aufsichtspflichtverletzung, hier nicht widerlegbar."], ["Niemand haftet, weil Mia deliktsunfähig ist.", "Falsch. Die Eltern können aus § 832 haften."], ["V haftet aus § 278 für Mia als Erfüllungsgehilfin.", "Falsch. § 278 setzt ein Schuldverhältnis voraus."], ["V haftet aus § 831, weil Mia seine Verrichtungsgehilfin ist.", "Falsch. Ein Kind ist keine Verrichtungsgehilfin."], ["V haftet nur, wenn er den Schaden vorsätzlich zugelassen hat.", "Falsch. Die Verletzung der Aufsichtspflicht genügt."]], "id": "P2-del-4"}, {"topic": "del", "sv": "Bauunternehmer U setzt den seit Jahren zuverlässigen und regelmäßig kontrollierten Arbeiter A ein. A lässt beim Abriss fahrlässig einen Stein fallen, der das Auto des Passanten P beschädigt.", "q": "Welche Ansprüche hat P?", "c": 5, "o": [["P hat gegen U einen Anspruch aus §§ 280 I, 278, weil A Erfüllungsgehilfe des U ist.", "Falsch. Zwischen P und U besteht kein Schuldverhältnis."], ["P hat gegen U einen Anspruch aus § 831, von dem U sich nicht entlasten kann.", "Falsch. U hat sorgfältig ausgewählt und überwacht (§ 831 I 2)."], ["P hat gegen niemanden einen Anspruch, weil A im Auftrag des U handelte.", "Falsch. A haftet persönlich aus § 823 I."], ["P hat gegen A nur einen Anspruch, wenn A grob fahrlässig war.", "Falsch. Jede Fahrlässigkeit genügt."], ["P kann von U und A je die Hälfte verlangen.", "Falsch. U haftet nicht; A haftet voll."], ["P kann von A aus § 823 I Ersatz verlangen; U kann sich nach § 831 I 2 entlasten.", "Richtig. Sorgfältige Auswahl und Überwachung."]], "id": "P2-del-5"}, {"topic": "del", "sv": "Hausbesitzer H streut trotz Glatteis vor seinem Haus nicht, obwohl ihn die Gemeindesatzung dazu verpflichtet. Briefträgerin B rutscht aus und verletzt sich.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 1, "o": [["H haftet nicht, weil er nichts getan, sondern nur unterlassen hat.", "Falsch. Bei einer Verkehrssicherungspflicht genügt Unterlassen."], ["H haftet aus § 823 I wegen Verletzung der Verkehrssicherungspflicht.", "Richtig. Pflichtwidriges Unterlassen bei bestehender Sicherungspflicht."], ["H haftet nur, wenn B einen Vertrag mit ihm hat.", "Falsch. Die deliktische Haftung setzt keinen Vertrag voraus."], ["H haftet nur, wenn B nachweist, dass H vorsätzlich nicht gestreut hat.", "Falsch. Fahrlässigkeit genügt."], ["Die Gemeinde haftet allein, weil sie die Satzung erlassen hat.", "Falsch. Die Pflicht ist auf H übertragen."], ["H haftet nur, wenn B dienstlich und nicht privat unterwegs war.", "Falsch. Der Zweck des Weges spielt keine Rolle."]], "id": "P2-del-6"}, {"topic": "del", "sv": "Der Hund des H reißt sich von der Leine und beißt Jogger J ins Bein. H hatte den Hund ordnungsgemäß angeleint; die Leine riss unvorhersehbar. Der Hund ist ein reines Familienhaustier.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 2, "o": [["H haftet nicht, weil er den Hund ordnungsgemäß angeleint hatte.", "Falsch. Bei Luxustieren gibt es keine Entlastung (§ 833 S. 2 gilt nur für Nutztiere)."], ["H haftet nur aus § 823 I, wenn ihn ein Verschulden trifft.", "Falsch. § 833 S. 1 ist verschuldensunabhängig."], ["H haftet aus § 833 S. 1 ohne Verschulden, weil der Hund ein Luxustier ist.", "Richtig. Gefährdungshaftung des Tierhalters."], ["Der Hersteller der Leine haftet allein, weil sie gerissen ist.", "Falsch. H haftet aus § 833 jedenfalls; der Hersteller allenfalls daneben."], ["H haftet nur, wenn der Hund schon früher gebissen hat.", "Falsch. Auf frühere Vorfälle kommt es nicht an."], ["J muss sich wegen des Joggens ein Mitverschulden von 50 % anrechnen lassen.", "Falsch. Joggen ist kein Mitverschulden."]], "id": "P2-del-7"}, {"topic": "del", "sv": "Schäfer S hält eine Herde als Erwerbsquelle. Trotz sorgfältig gewarteten Zauns bricht ein Schaf aus und beschädigt das Auto des A.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 5, "o": [["S haftet ohne Entlastungsmöglichkeit, weil jeder Tierhalter verschuldensunabhängig haftet.", "Falsch. Für Nutztiere gibt es die Entlastung nach § 833 S. 2."], ["S haftet nicht, weil Schafe keine gefährlichen Tiere sind.", "Falsch. Die Gefährlichkeit ist für § 833 ohne Bedeutung."], ["S haftet nur nach § 834 als Tieraufseher.", "Falsch. S ist Halter."], ["A muss beweisen, dass S den Zaun schlecht gewartet hat.", "Falsch. Das Verschulden wird vermutet; S muss sich entlasten."], ["S haftet aus § 823 I, weil das Schaf eine Sache ist.", "Falsch. § 833 ist hier die einschlägige Grundlage."], ["S kann sich als Halter eines Nutztiers entlasten.", "Richtig. Haustier, das dem Erwerb dient. (§ 833 S. 2)"]], "id": "P2-del-8"}, {"topic": "del", "sv": "Spaziergänger S wird von einem fremden, frei laufenden Kampfhund angegriffen. Er schlägt ihn mit einem Stock nieder; der Hund wird verletzt. Der Halter H verlangt die Tierarztkosten.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 4, "o": [["S muss zahlen, weil er den Hund vorsätzlich verletzt hat.", "Falsch. Die Handlung war gerechtfertigt."], ["S muss nicht zahlen, weil er in Notwehr gegen den Hund handelte (§ 227).", "Falsch. Notwehr setzt einen menschlichen Angriff voraus; hier greift § 228."], ["S muss die Hälfte zahlen, weil beide Seiten Schaden erlitten haben.", "Falsch. Gerechtfertigtes Handeln löst keinen Ersatz aus."], ["S muss zahlen, weil er nur hätte weglaufen dürfen.", "Falsch. Ein Ausweichen war nicht zumutbar; die Abwehr war erforderlich."], ["S muss nicht zahlen, weil er im Defensivnotstand handelte (§ 228).", "Richtig. Gefahr ging vom Tier aus, Abwehr erforderlich und verhältnismäßig."], ["S muss zahlen, weil § 228 nur für Sachen gilt und Tiere keine Sachen sind.", "Falsch. Die Vorschriften über Sachen gelten für Tiere entsprechend (§ 90a)."]], "id": "P2-del-9"}, {"topic": "del", "sv": "Hersteller H bringt einen Wasserkocher in Verkehr. Wegen eines Konstruktionsfehlers schmort ein Kabel; der Küchentisch des Privatkunden K (Wert 900 €) brennt an. Der Wasserkocher selbst (Wert 50 €) ist zerstört. H trifft kein Verschulden.", "q": "Was kann K nach dem ProdHaftG verlangen?", "c": 3, "o": [["950 € für Tisch und Wasserkocher.", "Falsch. Das fehlerhafte Produkt selbst wird nicht ersetzt (§ 1 I 2)."], ["900 € für den Tisch ohne Abzug.", "Falsch. Bei Sachschäden trägt der Geschädigte 500 € selbst (§ 11)."], ["Nichts, weil H kein Verschulden trifft.", "Falsch. Die Haftung nach dem ProdHaftG ist verschuldensunabhängig."], ["400 € (900 € abzüglich 500 €).", "Richtig. Andere, privat genutzte Sache; Selbstbeteiligung. (§§ 1, 11 ProdHaftG)"], ["Nur 50 € für den Wasserkocher.", "Falsch. Gerade der Wasserkocher ist nicht erfasst."], ["Nichts, weil K einen Kaufvertrag mit dem Händler, nicht mit H hat.", "Falsch. Das ProdHaftG setzt keinen Vertrag voraus."]], "id": "P2-del-10"}, {"topic": "del", "sv": "Hersteller H produziert E-Bikes. Ein Bremsseil reißt wegen eines Materialfehlers, der trotz aller zumutbaren Kontrollen nicht zu erkennen war („Ausreißer“). Fahrerin F stürzt und verletzt sich.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 0, "o": [["F hat einen Anspruch aus dem ProdHaftG, auch wenn H sich bei § 823 I entlastet.", "Richtig. Verschuldensunabhängige Haftung, auch für Ausreißer."], ["F hat gegen H keine Ansprüche, weil der Fehler nicht erkennbar war.", "Falsch. Nach dem ProdHaftG haftet H auch für Ausreißer."], ["F hat gegen H Ansprüche aus § 823 I, weil H für jeden Fehler ohne Entlastung haftet.", "Falsch. Bei Ausreißern kann sich H bei § 823 I entlasten."], ["F hat Ansprüche nur gegen den Händler, bei dem sie gekauft hat.", "Falsch. Das ProdHaftG richtet sich gegen den Hersteller."], ["F hat gegen H nur einen Anspruch auf Ersatz des E-Bikes.", "Falsch. Das Produkt selbst ist gerade nicht ersatzfähig."], ["F hat nur einen Anspruch, wenn sie beweist, dass H fahrlässig gehandelt hat.", "Falsch. Das ProdHaftG verlangt kein Verschulden."]], "id": "P2-del-11"}, {"topic": "del", "sv": "Zwei Autofahrer A und B verursachen fahrlässig gemeinsam einen Unfall, bei dem Fußgänger F verletzt wird (Schaden 10.000 €). Im Innenverhältnis trifft A 70 %, B 30 % Verantwortung. F verlangt alles von B.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 1, "o": [["B muss nur 3.000 € zahlen, weil er nur zu 30 % verantwortlich ist.", "Falsch. Im Außenverhältnis haftet jeder Gesamtschuldner auf das Ganze."], ["B muss 10.000 € zahlen und kann von A 7.000 € zurückverlangen.", "Richtig. Gesamtschuld, Ausgleich im Innenverhältnis. (§§ 840 I, 421, 426)"], ["F muss sich zuerst an A halten, weil A die Hauptschuld trägt.", "Falsch. F kann wählen (§ 421)."], ["B muss zahlen und hat keinen Ausgleichsanspruch gegen A.", "Falsch. Nach § 426 kann B Ausgleich verlangen."], ["F kann von A und B je 10.000 € verlangen.", "Falsch. Die Leistung kann nur einmal gefordert werden (§ 421)."], ["B muss nichts zahlen, weil A den Unfall überwiegend verursacht hat.", "Falsch. B haftet als Mitverursacher."]], "id": "P2-del-12"}, {"topic": "del", "sv": "Fußgänger F läuft bei Rot über die Ampel und wird von Autofahrer A angefahren, der 20 km/h zu schnell fuhr. Das Gericht bewertet die Verursachungsanteile mit 50 : 50.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 3, "o": [["F bekommt vollen Ersatz, weil A zu schnell fuhr.", "Falsch. Das Mitverschulden der F mindert den Anspruch (§ 254)."], ["F bekommt nichts, weil sie bei Rot gegangen ist.", "Falsch. Das Mitverschulden führt zur Kürzung, nicht zum Ausschluss."], ["F bekommt die Hälfte, aber kein Schmerzensgeld.", "Falsch. Auch das Schmerzensgeld wird nur gekürzt."], ["F bekommt die Hälfte, weil ihr Mitverschulden anzurechnen ist (§ 254 I).", "Richtig. Abwägung der Verursachungsbeiträge."], ["A muss zahlen, kann aber gegen F mit seinem eigenen Schaden in voller Höhe aufrechnen.", "Falsch. Auch A’s Anspruch wäre nach § 254 gekürzt."], ["F bekommt den vollen Ersatz, weil Fußgänger im Straßenverkehr immer geschützt sind.", "Falsch. Auch Fußgänger trifft § 254."]], "id": "P2-del-13"}, {"topic": "del", "sv": "Einbrecher E dringt in das Haus des H ein. H schlägt ihn mit einem Baseballschläger nieder, als E mit einem Messer auf ihn zukommt. E verlangt Schmerzensgeld.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 0, "o": [["E bekommt nichts, weil H in Notwehr handelte (§ 227).", "Richtig. Gegenwärtiger rechtswidriger Angriff, erforderliche Abwehr."], ["E bekommt Schmerzensgeld, weil H ihn vorsätzlich verletzt hat.", "Falsch. Die Verletzung war durch Notwehr gerechtfertigt."], ["E bekommt Schmerzensgeld, weil H die Polizei hätte rufen müssen.", "Falsch. Bei einem gegenwärtigen Angriff mit Messer ist sofortige Abwehr erlaubt."], ["E bekommt die Hälfte, weil beide sich falsch verhalten haben.", "Falsch. Gerechtfertigtes Handeln ist nicht rechtswidrig."], ["E bekommt nichts, weil Einbrecher generell keine Ansprüche haben.", "Falsch. „Generell“: Nur die Rechtfertigung im konkreten Fall schließt den Anspruch aus."], ["E bekommt nichts, weil H im Defensivnotstand gehandelt hat (§ 228).", "Falsch. Gegen den Angriff eines Menschen gilt Notwehr (§ 227)."]], "id": "P2-del-14"}, {"topic": "del", "sv": "Zeitungsverlag Z verbreitet über den Unternehmer U die erfundene Behauptung, er bestechte Beamte. U verliert Aufträge.", "q": "Welche Rechtsgüter bzw. Anspruchsgrundlagen kommen in Betracht?", "c": 5, "o": [["Nur § 823 I wegen Verletzung des Eigentums des U.", "Falsch. Das Eigentum ist nicht betroffen."], ["Keine, weil die Pressefreiheit jede Berichterstattung schützt.", "Falsch. Erfundene Tatsachen sind nicht geschützt."], ["Nur § 812, weil Z durch den Artikel bereichert ist.", "Falsch. Es geht um Delikt."], ["Nur ein Anspruch auf Gegendarstellung, kein Schadensersatz.", "Falsch. Daneben besteht Schadensersatz."], ["§ 831, weil Z für seine Journalisten haftet und sich nicht entlasten kann.", "Falsch. § 831 setzt eine Tat des Gehilfen voraus; vorrangig haftet Z selbst."], ["§ 823 I (allgemeines Persönlichkeitsrecht) und § 823 II i. V. m. § 186 StGB.", "Richtig. Sonstiges Recht und Schutzgesetz."]], "id": "P2-del-15"}, {"topic": "del", "sv": "Autofahrer A beschädigt fahrlässig den geparkten Wagen des B. Die Reparatur kostet laut Gutachten 4.000 € netto. B lässt nicht reparieren und verlangt das Geld.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 4, "o": [["B bekommt nichts, solange er nicht repariert.", "Falsch. Der Geschädigte darf fiktiv abrechnen (§ 249 II 1)."], ["B kann 4.760 € verlangen, weil der Gutachter brutto rechnen muss.", "Falsch. § 249 II 2: Umsatzsteuer nur bei Anfall."], ["B muss A die Reparatur selbst durchführen lassen.", "Falsch. Der Geschädigte kann Geld statt Herstellung verlangen."], ["B bekommt nur den Wertverlust, nicht die Reparaturkosten.", "Falsch. Ersatzfähig sind die erforderlichen Herstellungskosten."], ["4.000 € netto; Umsatzsteuer nur, wenn sie anfällt.", "Richtig. Fiktive Abrechnung. (§ 249 II)"], ["B bekommt die 4.000 € nur, wenn er sie innerhalb eines Jahres verwendet.", "Falsch. Eine Verwendungspflicht gibt es nicht."]], "id": "P2-del-16"}, {"topic": "del", "sv": "Hundehalterin H geht mit ihrem Hund spazieren. Ihr Nachbar N passt einen Nachmittag lang auf den Hund auf, weil H verreist ist. Der Hund beißt in dieser Zeit eine Passantin P, weil N ihn unachtsam frei laufen ließ.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 2, "o": [["Nur N haftet, weil er den Hund in diesem Moment beaufsichtigt hat.", "Falsch. H bleibt als Halterin nach § 833 haftbar."], ["Nur H haftet, weil N den Hund nur aus Gefälligkeit beaufsichtigt hat.", "Falsch. Auch N kann haften (§ 834 oder § 823 I)."], ["H haftet als Halterin aus § 833 S. 1, N daneben aus § 823 I.", "Richtig. Gefährdungshaftung der Halterin und Verschuldenshaftung des Aufpassers."], ["Niemand haftet, weil weder H noch N anwesend war, als der Hund biss.", "Falsch. N war anwesend; H haftet verschuldensunabhängig."], ["H haftet nur, wenn sie N nicht sorgfältig ausgewählt hat.", "Falsch. Die Halterhaftung für Luxustiere ist verschuldensunabhängig."], ["P bekommt nur die Hälfte, weil sie dem Hund hätte ausweichen müssen.", "Falsch. Ein Mitverschulden ist nicht ersichtlich."]], "id": "P2-del-17"}, {"topic": "del", "sv": "S verletzt fahrlässig den Familienvater V tödlich. V hinterlässt seine Ehefrau E und zwei Kinder, denen er Unterhalt schuldete.", "q": "Welche Ansprüche haben E und die Kinder gegen S?", "c": 5, "o": [["Keine, weil nur der unmittelbar Verletzte Ansprüche hat.", "Falsch. § 844 ist eine gesetzliche Ausnahme."], ["Nur Schmerzensgeld für den Verlust, aber keinen Unterhaltsersatz.", "Falsch. § 844 II gibt gerade den Unterhaltsersatz."], ["Nur einen Anspruch aus Vertrag, wenn S mit V verbunden war.", "Falsch. Die Ansprüche sind deliktisch."], ["Nur die Kinder haben Ansprüche, weil die Ehefrau erwerbsfähig ist.", "Falsch. Beide sind unterhaltsberechtigt."], ["E kann den gesamten Verdienst des V für 30 Jahre verlangen.", "Falsch. Ersetzt wird nur der entgangene Unterhalt."], ["Ersatz der Beerdigungskosten und des entgangenen Unterhalts.", "Richtig. Mittelbar Geschädigte haben ausnahmsweise eigene Ansprüche. (§§ 844 I, II)"]], "id": "P2-del-18"}, {"topic": "del", "sv": "Mitarbeiter M des Supermarkts S stellt einen Eimer mit Wasser mitten in den Gang. Kundin K stolpert und bricht sich den Fuß. S kann beweisen, dass M seit Jahren sorgfältig ausgewählt und kontrolliert wurde.", "q": "Welche Aussage zu den Ansprüchen gegen S ist richtig?", "c": 2, "o": [["K hat keinen Anspruch gegen S, weil S sich nach § 831 I 2 entlasten kann.", "Falsch. Vertragsähnlich haftet S über § 278 ohne Entlastung."], ["K hat nur einen Anspruch gegen M persönlich.", "Falsch. S haftet daneben über § 278."], ["K hat einen Anspruch aus §§ 280 I, 311 II, 241 II, 278 ohne Entlastungsmöglichkeit.", "Richtig. Zurechnung über § 278 ohne Entlastung."], ["K hat einen Anspruch gegen S nur, wenn sie bereits etwas gekauft hatte.", "Falsch. Schon die Vertragsanbahnung begründet Schutzpflichten (§ 311 II Nr. 2)."], ["K hat gegen S einen Anspruch aus § 831, weil der Entlastungsbeweis bei Supermärkten ausgeschlossen ist.", "Falsch. Der Entlastungsbeweis ist nicht ausgeschlossen; hier gelingt er sogar."], ["K hat keinen Anspruch auf Schmerzensgeld, weil nur ein vorvertragliches Verhältnis bestand.", "Falsch. § 253 II gilt für alle Anspruchsgrundlagen."]], "id": "P2-del-19"}, {"topic": "vs", "sv": "Im Schaufenster der Boutique B hängt ein Wollmantel mit dem Preisschild „49 €“; gemeint waren 490 €. Kundin K betritt den Laden und sagt: „Ich nehme den Mantel aus dem Fenster für 49 €.“ Die Verkäuferin lehnt ab.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 4, "o": [["Ein Vertrag über 49 € ist zustande gekommen, weil die Auslage ein bindendes Angebot ist.", "Falsch. Die Schaufensterauslage ist nur eine invitatio ad offerendum."], ["Ein Vertrag ist zustande gekommen, B kann ihn aber wegen Erklärungsirrtums anfechten.", "Falsch. Es fehlt schon am Vertrag."], ["Ein Vertrag über 490 € ist zustande gekommen, weil B das so gemeint hat.", "Falsch. Über 490 € hat K nichts erklärt."], ["Kein Vertrag, weil Verträge über mehr als 50 € schriftlich geschlossen werden müssen.", "Falsch. Der Kauf beweglicher Sachen ist formfrei."], ["Kein Vertrag: Erst die Erklärung der K ist ein Angebot, das B ablehnen durfte.", "Richtig. Auslage = Aufforderung zur Abgabe von Angeboten."], ["Ein Vertrag ist zustande gekommen, weil K das Angebot im Laden mündlich angenommen hat.", "Falsch. Es gab kein Angebot, das K hätte annehmen können."]], "id": "P2-vs-0"}, {"topic": "vs", "sv": "Kunde K bestellt im Onlineshop des H einen Fernseher. Wegen eines Systemfehlers steht er dort mit 99 € statt 999 € drin. K erhält sofort eine automatische E-Mail: „Vielen Dank, wir haben Ihre Bestellung erhalten und prüfen sie.“ Am nächsten Tag storniert H.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 5, "o": [["Ein Vertrag über 99 € besteht, weil die Darstellung im Shop ein Angebot ist.", "Falsch. Shopangebote sind regelmäßig invitatio ad offerendum."], ["Ein Vertrag besteht, weil die E-Mail die Annahme der Bestellung ist.", "Falsch. Sie bestätigt nach ihrem Wortlaut nur den Eingang."], ["Ein Vertrag besteht; H kann ihn nur mit Wirkung für die Zukunft kündigen.", "Falsch. Es gibt schon keinen Vertrag."], ["Ein Vertrag besteht, weil K Verbraucher ist und besonders geschützt wird.", "Falsch. Der Verbraucherschutz ersetzt keine Annahme."], ["Ein Vertrag über 999 € besteht, weil H diesen Preis wollte.", "Falsch. Über diesen Preis hat K nichts erklärt."], ["Kein Vertrag: Die Bestellung ist Angebot, die E-Mail nur Eingangsbestätigung.", "Richtig. Eingangsbestätigung nach § 312i I Nr. 3 ist keine Annahme."]], "id": "P2-vs-1"}, {"topic": "vs", "sv": "A bietet B am Telefon sein Motorrad für 4.000 € an. B sagt: „Ich überlege es mir bis morgen.“ A erwidert nichts. Am nächsten Tag ruft B an: „Ich nehme es.“ A hat es inzwischen an C verkauft.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 0, "o": [["Kein Vertrag: Das Angebot erlosch mit Ende des Telefonats (§§ 146, 147 I).", "Richtig. Unter Anwesenden nur sofortige Annahme."], ["Zwischen A und B ist ein Vertrag zustande gekommen, weil A der Bedenkzeit nicht widersprochen hat.", "Falsch. Schweigen ist keine Einräumung einer Frist."], ["Zwischen A und B ist ein Vertrag zustande gekommen, weil ein Angebot bei Abwesenden zwei Wochen gilt.", "Falsch. Ein Telefonat ist ein Gespräch unter Anwesenden (§ 147 I 2)."], ["Ein Vertrag ist zustande gekommen, A haftet aber nicht, weil er an C verkauft hat.", "Falsch. Es gibt keinen Vertrag."], ["Ein Vertrag ist zustande gekommen, weil A sein Angebot nicht ausdrücklich widerrufen hat.", "Falsch. Das Angebot ist von selbst erloschen."], ["Kein Vertrag, weil Motorräder nur schriftlich verkauft werden können.", "Falsch. Formfreiheit."]], "id": "P2-vs-2"}, {"topic": "vs", "sv": "V bietet K per Brief eine Maschine an: „Annahme bis 15. 3.“ K schickt seine Annahme am 10. 3. ab; ein Brief braucht normalerweise einen Tag. Wegen eines Poststreiks geht sie erst am 17. 3. zu. V sieht am Poststempel, dass K rechtzeitig abgeschickt hat, und reagiert nicht.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 2, "o": [["Kein Vertrag, weil die Annahme nach Ablauf der Frist zugegangen ist (§ 148).", "Falsch. Die Ausnahme des § 149 greift."], ["Kein Vertrag; die Annahme gilt als neues Angebot, das V annehmen könnte (§ 150 I).", "Falsch. § 149 S. 2 geht vor."], ["Ein Vertrag ist zustande gekommen, weil V die Verspätung nicht angezeigt hat.", "Richtig. Rechtzeitige Absendung, erkennbar; die Annahme gilt als nicht verspätet. (§ 149)"], ["Ein Vertrag ist zustande gekommen, weil es auf die Absendung ankommt und nicht auf den Zugang.", "Falsch. Grundsätzlich zählt der Zugang; nur § 149 hilft."], ["Ein Vertrag ist zustande gekommen, aber erst am 17. 3., wenn V ausdrücklich zustimmt.", "Falsch. Eine Zustimmung ist nicht nötig."], ["Kein Vertrag, weil ein Poststreik höhere Gewalt ist und alle Fristen hemmt.", "Falsch. Fristen für Annahmen werden nicht gehemmt."]], "id": "P2-vs-3"}, {"topic": "vs", "sv": "Großhändler G bietet Bäcker B 10 Tonnen Mehl zu 500 € je Tonne an. B antwortet umgehend: „Einverstanden, aber zu 480 € je Tonne.“ G reagiert nicht. Zwei Wochen später verlangt B Lieferung zu 480 €.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 3, "o": [["Ein Vertrag zu 500 € ist zustande gekommen, weil B grundsätzlich einverstanden war.", "Falsch. Eine Annahme unter Änderungen ist keine Annahme."], ["Ein Vertrag zu 480 € ist zustande gekommen, weil G nicht widersprochen hat.", "Falsch. Schweigen ist grundsätzlich keine Annahme."], ["Ein Vertrag zu 490 € ist zustande gekommen, weil der Mittelwert maßgeblich ist.", "Falsch. Es gibt keine solche Regel."], ["Kein Vertrag: Bs Antwort ist Ablehnung und neues Angebot, das G nicht angenommen hat.", "Richtig. Neues Angebot erfordert eine Annahme durch G. (§ 150 II)"], ["Ein Vertrag ist zustande gekommen; der Preis bestimmt G nach billigem Ermessen.", "Falsch. § 315 setzt eine Vereinbarung voraus."], ["Kein Vertrag, weil B das Angebot nicht schriftlich angenommen hat.", "Falsch. Annahmen sind formfrei."]], "id": "P2-vs-4"}, {"topic": "vs", "sv": "Die Kaufleute K1 und K2 vereinbaren am Telefon die Lieferung von 500 Paletten. Am nächsten Tag schickt K1 ein Schreiben: „Wir bestätigen unser Telefonat: 500 Paletten, Zahlung 30 Tage nach Lieferung.“ Über das Zahlungsziel war nicht gesprochen worden. K2 reagiert nicht.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 1, "o": [["Das Zahlungsziel gilt nicht, weil Schweigen nie als Zustimmung gilt.", "Falsch. Unter Kaufleuten gelten die Regeln zum kaufmännischen Bestätigungsschreiben."], ["Es gilt der Inhalt des Schreibens, weil K2 nicht unverzüglich widersprach.", "Richtig. Kaufmännisches Bestätigungsschreiben; keine grobe Abweichung."], ["Der Vertrag ist erst mit dem Schreiben zustande gekommen; vorher bestand nichts.", "Falsch. Der Vertrag bestand schon; das Schreiben legt den Inhalt fest."], ["Das Zahlungsziel gilt nur, wenn K2 das Schreiben unterschreibt und zurückschickt.", "Falsch. Gerade das Schweigen wirkt."], ["Der gesamte Vertrag ist unwirksam, weil sich Telefonat und Schreiben widersprechen.", "Falsch. Die Ergänzung widerspricht nicht, sie ergänzt."], ["Das Zahlungsziel gilt, weil K1 als Verkäufer die Bedingungen einseitig festlegen darf.", "Falsch. Es gibt kein einseitiges Bestimmungsrecht."]], "id": "P2-vs-5"}, {"topic": "vs", "sv": "Verlag U schickt der Studentin S unaufgefordert ein Lehrbuch mit Rechnung: „Wenn Sie das Buch nicht binnen 10 Tagen zurücksenden, gilt der Kauf als vereinbart.“ S stellt das Buch ins Regal und reagiert nicht.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 1, "o": [["Ein Vertrag ist zustande gekommen, weil S nicht fristgerecht widersprochen hat.", "Falsch. Schweigen ist keine Annahme; § 241a schützt Verbraucher zusätzlich."], ["Kein Vertrag; U hat keinen Anspruch auf Zahlung des Kaufpreises (§ 241a I).", "Richtig. Unbestellte Leistung an einen Verbraucher."], ["Ein Vertrag ist zustande gekommen, S kann ihn aber binnen 14 Tagen widerrufen.", "Falsch. Es gibt schon keinen Vertrag."], ["Kein Vertrag, S muss das Buch aber auf eigene Kosten zurücksenden.", "Falsch. Eine Rücksendepflicht besteht nicht."], ["Kein Vertrag, S muss aber für die Nutzung des Buches Wertersatz leisten.", "Falsch. § 241a I schließt Ansprüche gegen S aus."], ["Ein Vertrag ist zustande gekommen, weil S das Buch behalten hat.", "Falsch. Bloßes Behalten ist keine Annahme."]], "id": "P2-vs-6"}, {"topic": "vs", "sv": "Vermieter V wirft am 31. 3. um 23:30 Uhr eine Kündigung in den Hausbriefkasten seines Mieters M. M leert den Briefkasten am 1. 4. um 9 Uhr.", "q": "Wann ist die Kündigung zugegangen?", "c": 5, "o": [["Am 31. 3. um 23:30 Uhr, weil es nur auf den Einwurf ankommt.", "Falsch. Einwurf allein genügt nicht; es kommt auf die zu erwartende Kenntnisnahme an."], ["Am 1. 4. um 9 Uhr, weil es auf die tatsächliche Kenntnisnahme ankommt.", "Falsch. Maßgeblich ist die zu erwartende, nicht die tatsächliche Kenntnisnahme."], ["Am 31. 3., weil V die Kündigung vor Mitternacht abgegeben hat.", "Falsch. Abgabe und Zugang sind zu trennen."], ["Erst, wenn M den Brief tatsächlich öffnet und liest.", "Falsch. Auf das Lesen kommt es nicht an."], ["Gar nicht, weil Kündigungen persönlich übergeben werden müssen.", "Falsch. Der Einwurf in den Briefkasten genügt."], ["Am 1. 4., weil mit einer Leerung erst am nächsten Tag zu rechnen ist.", "Richtig. Zugang, sobald unter normalen Umständen mit Kenntnisnahme zu rechnen ist."]], "id": "P2-vs-7"}, {"topic": "vs", "sv": "Lieferant L schickt der Firma F am Sonntag um 14 Uhr eine E-Mail mit der Annahme eines Angebots. Die Geschäftszeiten von F sind Montag bis Freitag, 8–17 Uhr. Die Mitarbeiterin liest die Mail am Montag um 11 Uhr.", "q": "Wann ist die Annahme zugegangen?", "c": 4, "o": [["Am Sonntag um 14 Uhr, weil E-Mails sofort im Postfach ankommen.", "Falsch. Bei Unternehmern zählen die Geschäftszeiten."], ["Am Montag um 11 Uhr, weil die Mail erst dann gelesen wurde.", "Falsch. Auf das tatsächliche Lesen kommt es nicht an."], ["Erst nach einer Lesebestätigung.", "Falsch. Eine Lesebestätigung ist nicht nötig."], ["Gar nicht, weil Annahmen per E-Mail unwirksam sind.", "Falsch. Eine Form ist nicht vorgeschrieben."], ["Am Montag um 8 Uhr, weil erst dann mit Kenntnisnahme zu rechnen ist.", "Richtig. Zugang bei gewöhnlicher Möglichkeit der Kenntnisnahme."], ["Am Sonntag, weil Sonntage bei Fristen nicht zählen und daher alles sofort wirkt.", "Falsch. Das verwechselt § 193 mit dem Zugang."]], "id": "P2-vs-8"}, {"topic": "vs", "sv": "A wirft am Montag um 10 Uhr ein schriftliches Kaufangebot in den Briefkasten des B. Bereits um 9 Uhr hatte er B eine E-Mail geschickt: „Mein Angebot, das heute bei dir eingeht, ist hinfällig.“ B liest am Abend zuerst den Brief, dann die E-Mail, und erklärt sofort die Annahme.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 0, "o": [["Kein Vertrag, weil der Widerruf vor dem Angebot zugegangen ist (§ 130 I 2).", "Richtig. Das Angebot wurde nie wirksam."], ["Ein Vertrag besteht, weil B den Brief zuerst gelesen hat.", "Falsch. Es kommt auf den Zugang an, nicht auf die Reihenfolge des Lesens."], ["Ein Vertrag besteht, weil ein Angebot nur mit der gleichen Form widerrufen werden kann.", "Falsch. Für den Widerruf gibt es keine Formbindung."], ["Ein Vertrag besteht, weil der Widerruf erst nach Absendung des Angebots erklärt wurde.", "Falsch. Entscheidend ist der Zugang vor oder gleichzeitig mit dem Angebot."], ["Ein Vertrag besteht, weil A an sein Angebot gebunden war (§ 145).", "Falsch. Die Bindung tritt erst mit dem Zugang ein; der Widerruf ging vorher zu."], ["Kein Vertrag, weil B das Angebot zu spät angenommen hat.", "Falsch. Die Annahme war nicht verspätet; es gab kein Angebot mehr."]], "id": "P2-vs-9"}, {"topic": "vs", "sv": "Sammler S schickt Händler H ein schriftliches Angebot zum Kauf einer seltenen Münze. S stirbt, bevor der Brief bei H ankommt. H weiß davon nichts und nimmt das Angebot an. S’ Erbin E will die Münze nicht.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 3, "o": [["Kein Vertrag, weil das Angebot mit dem Tod des S erloschen ist.", "Falsch. § 153: Tod hindert das Zustandekommen grundsätzlich nicht."], ["Kein Vertrag, weil ein Toter keine Willenserklärung abgeben kann.", "Falsch. Die Erklärung war schon abgegeben (§ 130 II)."], ["Der Vertrag kommt nur zustande, wenn E zustimmt.", "Falsch. Eine Zustimmung ist nicht nötig."], ["Der Vertrag kommt mit E als Erbin zustande (§ 153).", "Richtig. Ein anderer Wille des S ist nicht ersichtlich. (§§ 130 II, 153)"], ["Der Vertrag ist schwebend unwirksam, bis das Nachlassgericht entscheidet.", "Falsch. Es gibt keine solche Genehmigung."], ["Der Vertrag kommt nur zustande, wenn H vom Tod wusste.", "Falsch. Die Unkenntnis ist gerade unerheblich."]], "id": "P2-vs-10"}, {"topic": "vs", "sv": "Ein Bote übergibt um 10 Uhr ein an M adressiertes Kündigungsschreiben dessen Ehefrau F an der Wohnungstür. M kommt um 19 Uhr nach Hause; F vergisst, ihm den Brief zu geben, und findet ihn erst nach einer Woche wieder.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 2, "o": [["Die Kündigung ging erst nach einer Woche zu, als M den Brief tatsächlich erhielt.", "Falsch. F war Empfangsbotin; das Risiko trägt M."], ["Die Kündigung ging um 10 Uhr zu, weil F den Brief entgegengenommen hat.", "Falsch. Beim Empfangsboten kommt es auf die zu erwartende Weitergabe an."], ["Die Kündigung ging am Abend zu, weil dann die Weitergabe zu erwarten war.", "Richtig. Empfangsbote: Zugang bei regelmäßigem Ablauf der Weitergabe."], ["Die Kündigung ging nie zu, weil sie M persönlich ausgehändigt werden musste.", "Falsch. Die Übergabe an Empfangsboten genügt."], ["Die Kündigung ging nie zu, weil F als Erklärungsbotin des Absenders handelte.", "Falsch. F ist Empfangsbotin des M."], ["Die Kündigung ging zu, sobald M von ihr erfuhr, gleich wann.", "Falsch. Es zählt der regelmäßige Ablauf."]], "id": "P2-vs-11"}, {"topic": "vs", "sv": "Fünf Kollegen spielen seit Jahren gemeinsam Lotto; K füllt jede Woche den Schein mit den „Stammzahlen“ aus und gibt ihn ab. Einmal vergisst er es. Genau in dieser Woche wären die Zahlen gezogen worden. Die anderen verlangen von K je ihren Gewinnanteil.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 2, "o": [["K haftet aus §§ 280 I, 705 BGB, weil eine Gesellschaft bürgerlichen Rechts mit Abgabepflicht besteht.", "Falsch. Für die Abgabe fehlt ein Rechtsbindungswille."], ["K haftet aus § 823 I, weil er das Vermögen der anderen fahrlässig verletzt hat.", "Falsch. Das Vermögen ist kein Rechtsgut des § 823 I."], ["K haftet nicht, weil für die Abgabe des Scheins kein Rechtsbindungswille bestand.", "Richtig. Gefälligkeit; das Haftungsrisiko wollte niemand übernehmen (BGH)."], ["K haftet nur, wenn er grob fahrlässig gehandelt hat.", "Falsch. Es fehlt schon an einer vertraglichen Pflicht."], ["K haftet in voller Höhe, weil er die Pflicht freiwillig übernommen hat.", "Falsch. Freiwilligkeit begründet keine Bindung."], ["K haftet nicht, weil Spielschulden nicht einklagbar sind (§ 762).", "Falsch. Es geht nicht um eine Spielschuld."]], "id": "P2-vs-12"}, {"topic": "vs", "sv": "Weinhändler W und Gastwirt G vereinbaren mündlich „einen Karton Merlot“. Bei W enthält ein „Karton“ üblicherweise 6 Flaschen. W und G meinen aber beide den 12er-Karton, den G immer bestellt.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 3, "o": [["Ein Vertrag über 6 Flaschen ist zustande gekommen, weil der objektive Erklärungswert zählt.", "Falsch. Das übereinstimmend Gewollte geht vor."], ["Kein Vertrag wegen versteckten Dissenses (§ 155).", "Falsch. Es gibt keinen Dissens; beide wollten dasselbe."], ["Ein Vertrag über 6 Flaschen ist zustande gekommen, G kann aber anfechten.", "Falsch. Ein Irrtum liegt nicht vor."], ["Ein Vertrag über 12 Flaschen ist zustande gekommen, weil beide dasselbe meinten.", "Richtig. Falsa demonstratio non nocet."], ["Kein Vertrag, weil die Menge nicht bestimmt war.", "Falsch. Die Menge ist durch Auslegung bestimmt."], ["Ein Vertrag über 12 Flaschen ist zustande gekommen, aber nur wenn er schriftlich bestätigt wird.", "Falsch. Eine Bestätigung ist nicht nötig."]], "id": "P2-vs-13"}, {"topic": "vs", "sv": "Der deutsche Händler H und der Kanadier K vereinbaren einen Preis von „10.000 Dollar“. H meint US-Dollar, K kanadische Dollar. Aus den Umständen lässt sich nicht ermitteln, welche Währung gemeint war.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 0, "o": [["Kein Vertrag, weil über einen wesentlichen Punkt ein versteckter Dissens besteht.", "Richtig. Objektiv mehrdeutig, Preis ist wesentlich. (§ 155)"], ["Ein Vertrag in US-Dollar ist zustande gekommen, weil der US-Dollar die Leitwährung ist.", "Falsch. Eine solche Auslegungsregel gibt es nicht."], ["Ein Vertrag in kanadischen Dollar ist zustande gekommen, weil K aus Kanada kommt.", "Falsch. Die Herkunft allein entscheidet nicht."], ["Ein Vertrag ist zustande gekommen; jede Partei kann ihn wegen Inhaltsirrtums anfechten.", "Falsch. Es fehlt schon am Konsens."], ["Ein Vertrag ist zustande gekommen; der Preis wird in Euro umgerechnet.", "Falsch. Die Parteien haben sich auf keine Währung geeinigt."], ["Ein Vertrag ist zustande gekommen, weil beide „Dollar“ gesagt haben.", "Falsch. Der Wortlaut ist gerade mehrdeutig."]], "id": "P2-vs-14"}, {"topic": "vs", "sv": "Unternehmer U und Lieferant L haben sich über Ware und Preis geeinigt. Beide wissen, dass der Liefertermin noch offen ist, und vereinbaren, ihn nächste Woche festzulegen. Dazu kommt es nicht.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 5, "o": [["Ein Vertrag besteht; der Liefertermin richtet sich nach § 271 (sofort).", "Falsch. Die Parteien wollten den Punkt gerade selbst regeln."], ["Ein Vertrag besteht, weil Ware und Preis feststehen.", "Falsch. Bei offenem Dissens gilt die Zweifelsregel des § 154 I."], ["Ein Vertrag besteht, weil der Liefertermin nur eine Nebenabrede ist.", "Falsch. Die Parteien hielten ihn für regelungsbedürftig."], ["Kein Vertrag wegen versteckten Dissenses (§ 155).", "Falsch. Der Dissens ist beiden bekannt, also offen."], ["Ein Vertrag besteht; L darf den Termin nach billigem Ermessen bestimmen (§ 315).", "Falsch. Ein Bestimmungsrecht wurde nicht vereinbart."], ["Im Zweifel ist kein Vertrag geschlossen (offener Dissens, § 154 I).", "Richtig. Offener Dissens."]], "id": "P2-vs-15"}, {"topic": "vs", "sv": "Am Bahnhof steht ein Getränkeautomat des Betreibers B. Reisender R wirft 2 € ein und drückt auf „Wasser“. Der Automat funktioniert und gibt eine Flasche aus.", "q": "Wie ist der Vertrag zustande gekommen?", "c": 4, "o": [["Durch Angebot des R beim Geldeinwurf und Annahme des B, als er den Automaten nachfüllte.", "Falsch. Das Nachfüllen ist keine Annahme gegenüber R."], ["Gar nicht, weil man mit einer Maschine keinen Vertrag schließen kann.", "Falsch. Der Vertrag wird mit dem Betreiber geschlossen."], ["Erst mit der Entnahme der Flasche durch R, weil dann die Übereignung erfolgt.", "Falsch. Das betrifft das dingliche Geschäft."], ["Durch Angebot des R; der Automat nimmt im Namen des B als Vertreter an.", "Falsch. Ein Automat ist kein Vertreter."], ["Durch Angebot des B an jedermann mit dem Aufstellen und Annahme des R durch Geldeinwurf.", "Richtig. Angebot ad incertas personas, bedingt durch Vorrat und Funktion."], ["Nur durch Realakt; ein Kaufvertrag ist bei Automaten entbehrlich.", "Falsch. Auch hier gibt es einen Kaufvertrag."]], "id": "P2-vs-16"}, {"topic": "vs", "sv": "V stellt seinen Gebrauchtwagen (Wert 5.000 €) auf einer Auktionsplattform mit Startpreis 1 € ein. Kurz nach Beginn bricht er die Auktion ohne Grund ab; zu diesem Zeitpunkt hat nur K 1 € geboten. K verlangt Schadensersatz.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 1, "o": [["Kein Vertrag, weil das Einstellen nur eine invitatio ad offerendum ist.", "Falsch. Das Einstellen ist ein Angebot an den Höchstbietenden."], ["Ein Vertrag über 1 € besteht; K kann Schadensersatz statt der Leistung verlangen.", "Richtig. BGH: kein Rechtsmissbrauch trotz geringen Gebots."], ["Ein Vertrag ist zustande gekommen, aber wegen Wuchers nichtig (§ 138 II).", "Falsch. Ein Wucher setzt eine Ausbeutung voraus."], ["Kein Vertrag, weil die Auktion vor Ablauf beendet wurde.", "Falsch. Der Abbruch hebt den Vertrag nicht auf."], ["Ein Vertrag ist zustande gekommen, aber über den Marktwert von 5.000 €.", "Falsch. Preis ist das Höchstgebot."], ["Ein Vertrag ist zustande gekommen; V kann sich durch Zahlung von 1 € befreien.", "Falsch. V schuldet das Auto oder Schadensersatz."]], "id": "P2-vs-17"}, {"topic": "vs", "sv": "Auf einer Weinversteigerung hebt Gast G die Hand, um einem Freund zuzuwinken. Er weiß nicht, dass Handheben dort als Gebot gilt. Der Versteigerer erteilt ihm den Zuschlag. G hätte die Bedeutung bei Aufmerksamkeit erkennen können.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 5, "o": [["Kein Vertrag, weil G kein Erklärungsbewusstsein hatte.", "Falsch. Nach BGH genügt die zurechenbare Erklärung."], ["Ein Vertrag ist zustande gekommen; G kann sich davon nicht lösen.", "Falsch. Er kann anfechten."], ["Der Vertrag ist nichtig, weil G die Hand nur aus Spaß hob (§ 118).", "Falsch. G wollte keine Scherzerklärung abgeben."], ["Ein Vertrag ist zustande gekommen, wenn G den Wein abholt.", "Falsch. Der Zuschlag schließt den Vertrag (§ 156)."], ["Es liegt eine Willenserklärung vor; der Versteigerer muss sie anfechten.", "Falsch. Anfechtungsberechtigt ist G."], ["Es liegt eine anfechtbare Willenserklärung vor; G haftet nach § 122.", "Richtig. Fehlendes Erklärungsbewusstsein; Anfechtung analog § 119 I."]], "id": "P2-vs-18"}, {"topic": "vs", "sv": "Kunde K bestellt bei Versandhändler V schriftlich eine Bohrmaschine. V antwortet nicht, packt die Maschine aber noch am selben Tag ein und schickt sie los. K storniert per E-Mail, bevor das Paket ankommt.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 1, "o": [["Kein Vertrag, weil V keine Annahmeerklärung an K geschickt hat.", "Falsch. § 151 lässt die Annahme ohne Zugang genügen."], ["Der Vertrag kam bereits mit dem Versand der Maschine zustande (§ 151).", "Richtig. Annahme durch Betätigung des Willens."], ["Ein Vertrag kommt erst mit der Lieferung zustande.", "Falsch. Die Annahme lag schon im Versand."], ["Kein Vertrag, weil K vor Zugang der Ware storniert hat.", "Falsch. Der Vertrag war schon geschlossen."], ["Ein Vertrag ist zustande gekommen, aber nur, wenn K die Ware behält.", "Falsch. Das Behalten ist ohne Bedeutung."], ["Kein Vertrag, weil Schweigen nie eine Annahme ist.", "Falsch. V hat nicht geschwiegen, sondern versandt."]], "id": "P2-vs-19"}, {"topic": "vs", "sv": "Im Supermarkt legt Kundin K eine Flasche Olivenöl in den Wagen. Auf dem Weg zur Kasse überlegt sie es sich anders und stellt das Öl zurück ins Regal. Der Marktleiter meint, sie habe die Flasche bereits gekauft.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 0, "o": [["Kein Vertrag; er kommt erst beim Registrieren an der Kasse zustande.", "Richtig. Selbstbedienung: Vertragsschluss an der Kasse."], ["Der Vertrag kam mit dem Einlegen in den Wagen zustande, weil das Regal ein Angebot ist.", "Falsch. Nach h. M. ist die Warenauslage eine invitatio ad offerendum."], ["Der Vertrag kam zustande, K kann aber binnen 14 Tagen widerrufen.", "Falsch. Im Laden gibt es kein Widerrufsrecht; hier fehlt schon der Vertrag."], ["Der Vertrag kam zustande, weil K die Ware in Besitz genommen hat.", "Falsch. Der Besitz begründet keinen Vertrag."], ["Der Vertrag kam zustande, wurde aber durch das Zurückstellen konkludent aufgehoben.", "Falsch. Es gab noch nichts aufzuheben."], ["Kein Vertrag, weil ein Kauf erst mit der Zahlung zustande kommt.", "Falsch. Die Zahlung ist Erfüllung, nicht Vertragsschluss."]], "id": "P2-vs-20"}, {"topic": "agb", "sv": "Verbraucherin V bestellt am Montag, 2. 3. 2026, online bei Händler H eine Jacke und wird ordnungsgemäß über ihr Widerrufsrecht belehrt. Die Jacke wird ihr am Samstag, 7. 3. 2026, geliefert.", "q": "Bis wann kann V widerrufen?", "c": 5, "o": [["Bis Montag, 16. 3. 2026, weil die Frist mit der Bestellung beginnt.", "Falsch. Beim Warenkauf beginnt sie mit Erhalt der Ware (§ 356 II Nr. 1a)."], ["Bis Samstag, 21. 3. 2026, 24 Uhr, weil Samstage bei Fristen wie Werktage zählen.", "Falsch. § 193 verschiebt das Ende auf den nächsten Werktag."], ["Bis Freitag, 20. 3. 2026, weil der Liefertag mitgezählt wird.", "Falsch. Der Ereignistag zählt nicht mit (§ 187 I)."], ["Bis Dienstag, 7. 4. 2026, weil die Widerrufsfrist einen Monat beträgt.", "Falsch. Sie beträgt 14 Tage (§ 355 II 1)."], ["Gar nicht, weil V die Jacke bereits anprobiert hat.", "Falsch. Das Anprobieren ist Prüfung und schließt den Widerruf nicht aus."], ["Bis Montag, 23. 3. 2026, weil das Fristende auf einen Samstag fiele (§ 193).", "Richtig. Fristende Samstag, 21. 3. → Montag, 23. 3. (§§ 187 I, 188 I, 193)"]], "id": "P2-frist-0"}, {"topic": "agb", "sv": "Verbraucher K hat online einen Kopfhörer gekauft. Die Widerrufsfrist endet am Dienstag um 24 Uhr. K wirft am Dienstagabend einen Widerrufsbrief in den Briefkasten der Post; H erhält ihn am Donnerstag.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 2, "o": [["Der Widerruf ist verspätet, weil er erst nach Fristablauf zugegangen ist.", "Falsch. Für den Widerruf genügt die rechtzeitige Absendung (§ 355 I)."], ["Der Widerruf ist verspätet, weil er per E-Mail hätte erfolgen müssen.", "Falsch. Eine bestimmte Form ist nicht vorgeschrieben."], ["Der Widerruf ist rechtzeitig, weil die Absendung innerhalb der Frist genügt.", "Richtig. § 355 I: rechtzeitige Absendung wahrt die Frist."], ["Der Widerruf ist unwirksam, weil K keinen Grund angegeben hat.", "Falsch. Eine Begründung ist nicht nötig (§ 355 I)."], ["Der Widerruf ist nur wirksam, wenn K den Kopfhörer ebenfalls bis Dienstag zurückgeschickt hat.", "Falsch. Die Rücksendung ist eine Folge des Widerrufs, keine Voraussetzung."], ["Der Widerruf ist wirksam, aber erst ab Donnerstag; bis dahin schuldet K den Kaufpreis.", "Falsch. Er wirkt auf den Vertrag insgesamt."]], "id": "P2-frist-1"}, {"topic": "agb", "sv": "Verbraucherin V kauft am 10. 1. 2025 online ein Tablet; es wird am selben Tag geliefert. Eine Widerrufsbelehrung erhält sie nie. Am 20. 12. 2025 erklärt sie den Widerruf.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 0, "o": [["Rechtzeitig; ohne Belehrung erlischt das Recht erst nach 12 Monaten und 14 Tagen (§ 356 III 2).", "Richtig. Fristende frühestens im Januar 2026."], ["Der Widerruf ist verspätet, weil die 14-Tage-Frist im Januar 2025 abgelaufen ist.", "Falsch. Ohne Belehrung beginnt die Frist nicht."], ["Der Widerruf ist rechtzeitig, weil ein Widerrufsrecht ohne Belehrung unbefristet besteht.", "Falsch. Es erlischt spätestens nach 12 Monaten und 14 Tagen."], ["Der Widerruf ist verspätet, weil die Höchstfrist sechs Monate beträgt.", "Falsch. Sie beträgt 12 Monate und 14 Tage."], ["Der Widerruf ist unwirksam, weil V das Tablet fast ein Jahr benutzt hat.", "Falsch. Die Nutzung schließt den Widerruf nicht aus; es kann Wertersatz anfallen."], ["Der Widerruf ist nur möglich, wenn das Tablet mangelhaft ist.", "Falsch. Der Widerruf setzt keinen Mangel voraus."]], "id": "P2-frist-2"}, {"topic": "agb", "sv": "Verbraucher K konfiguriert im Onlineshop eines Schneiders einen Anzug nach seinen eigenen Maßen, Stoff- und Knopfwünschen. Nach Erhalt gefällt er ihm nicht, und er erklärt fristgerecht den Widerruf.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 3, "o": [["Der Widerruf ist wirksam, weil jeder Fernabsatzvertrag widerrufen werden kann.", "Falsch. § 312g II enthält Ausnahmen."], ["Der Widerruf ist wirksam, weil K Verbraucher ist und der Anzug ihm nicht gefällt.", "Falsch. Das Gefallen ist ohne Bedeutung; maßgeblich ist der Ausnahmetatbestand."], ["Der Widerruf ist wirksam, K muss aber Wertersatz für die Anfertigung leisten.", "Falsch. Ein Widerrufsrecht besteht schon nicht."], ["Kein Widerrufsrecht, weil der Anzug nach Kundenspezifikation gefertigt wurde.", "Richtig. Individuell angefertigte Ware. (§ 312g II Nr. 1)"], ["Ein Widerrufsrecht besteht nicht, weil es sich um einen Werkvertrag handelt.", "Falsch. Grund ist die Anfertigung nach Kundenwunsch, nicht der Vertragstyp."], ["Ein Widerrufsrecht besteht nur, wenn K den Anzug nicht getragen hat.", "Falsch. Das Tragen ist für § 312g II Nr. 1 ohne Bedeutung."]], "id": "P2-frist-3"}, {"topic": "agb", "sv": "Verbraucherin V kauft online eine Matratze. Sie entfernt die Schutzfolie, schläft zwei Nächte probe und widerruft dann fristgerecht. Der Händler beruft sich auf § 312g II Nr. 3 (versiegelte Waren, die aus Hygienegründen nicht zur Rückgabe geeignet sind).", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 1, "o": [["Der Widerruf ist ausgeschlossen, weil die Versiegelung entfernt wurde.", "Falsch. Matratzen fallen nach dem EuGH nicht unter die Ausnahme."], ["Der Widerruf ist möglich; die Hygieneausnahme greift bei Matratzen nicht.", "Richtig. Vergleichbar mit Kleidung; die Ausnahme greift nicht."], ["Der Widerruf ist ausgeschlossen, weil V die Matratze benutzt hat.", "Falsch. Die Nutzung schließt den Widerruf nicht aus."], ["Der Widerruf ist möglich, aber nur, wenn V die Folie wieder anbringt.", "Falsch. Das verlangt das Gesetz nicht."], ["Der Widerruf ist ausgeschlossen, weil Matratzen Hygieneartikel wie Zahnbürsten sind.", "Falsch. Der EuGH hat das gerade verneint."], ["Der Widerruf ist möglich, weil die Ausnahme nur für Lebensmittel gilt.", "Falsch. Sie gilt für alle versiegelten Hygienewaren."]], "id": "P2-frist-4"}, {"topic": "agb", "sv": "Kundin K kauft in einem Elektrofachmarkt vor Ort einen Staubsauger. Zuhause gefällt er ihr nicht. Sie verlangt binnen einer Woche den Kaufpreis zurück; der Markt bietet keine freiwillige Rücknahme an.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 4, "o": [["K kann widerrufen, weil jedem Verbraucher 14 Tage Widerrufsrecht zustehen.", "Falsch. Ein gesetzliches Widerrufsrecht gibt es nur bei Fernabsatz und außerhalb von Geschäftsräumen."], ["K kann widerrufen, weil der Staubsauger noch originalverpackt ist.", "Falsch. Die Verpackung spielt keine Rolle."], ["K kann vom Vertrag zurücktreten, weil der Staubsauger ihr nicht gefällt.", "Falsch. Ein Rücktritt setzt einen Mangel voraus."], ["K kann den Vertrag anfechten, weil sie sich über ihren Geschmack geirrt hat.", "Falsch. Ein Motivirrtum ist unbeachtlich."], ["Kein Anspruch: Im Laden besteht kein gesetzliches Widerrufsrecht.", "Richtig. Nur Kulanz oder ein vertragliches Rückgaberecht."], ["K kann nur Umtausch gegen einen anderen Staubsauger verlangen.", "Falsch. Auch ein Umtauschrecht besteht gesetzlich nicht."]], "id": "P2-frist-5"}, {"topic": "agb", "sv": "Verbraucherin V kauft online eine Kaffeemaschine und wird ordnungsgemäß belehrt. Sie benutzt sie zehn Tage lang täglich und entkalkt sie nicht. Dann widerruft sie. Die Maschine hat dadurch an Wert verloren.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 3, "o": [["Der Widerruf ist ausgeschlossen, weil V die Maschine benutzt hat.", "Falsch. Die Nutzung schließt den Widerruf nicht aus."], ["Der Widerruf ist wirksam; V muss keinen Ersatz leisten, weil sie belehrt wurde.", "Falsch. Gerade die Belehrung ist Voraussetzung für die Wertersatzpflicht."], ["Der Widerruf ist wirksam; V schuldet den vollen Kaufpreis als Wertersatz.", "Falsch. Ersetzt wird nur der Wertverlust."], ["Wirksam; V schuldet aber Wertersatz für den Wertverlust (§ 357a I).", "Richtig. Prüfung wie im Laden wäre ersatzfrei gewesen."], ["Der Widerruf ist wirksam, aber erst nach Reinigung der Maschine.", "Falsch. Die Wirksamkeit hängt nicht davon ab."], ["Der Widerruf ist wirksam; Ersatz kann H nur bei Vorsatz der V verlangen.", "Falsch. Ein Verschulden ist nicht vorausgesetzt."]], "id": "P2-frist-6"}, {"topic": "agb", "sv": "Verbraucher K ruft innerhalb der Widerrufsfrist beim Onlinehändler H an und sagt: „Ich will den Vertrag über den Drucker nicht mehr, ich widerrufe.“ Einen Grund nennt er nicht. H meint, der Widerruf müsse schriftlich und begründet sein.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 0, "o": [["Der Widerruf ist wirksam; Form und Begründung sind nicht nötig.", "Richtig. Telefonisch möglich; K trägt aber das Beweisrisiko. (§ 355 I)"], ["H hat recht, weil ein Widerruf der Textform bedarf.", "Falsch. Der Widerruf ist an keine Form gebunden."], ["H hat recht, weil ein Widerruf ohne Grund rechtsmissbräuchlich ist.", "Falsch. Eine Begründung ist nicht nötig."], ["Der Widerruf ist nur wirksam, wenn K das Muster-Widerrufsformular verwendet.", "Falsch. Das Formular ist freiwillig."], ["Der Widerruf ist nur wirksam, wenn H ihn schriftlich bestätigt.", "Falsch. Eine Bestätigung ist nicht Voraussetzung."], ["Der Widerruf ist erst mit Rücksendung des Druckers wirksam.", "Falsch. Er wird mit Zugang der Erklärung wirksam."]], "id": "P2-frist-7"}, {"topic": "agb", "sv": "Verbraucherin V hat fristgerecht den Kauf eines Mixers (Onlinekauf) widerrufen. Sie hat den Mixer noch nicht zurückgeschickt. Händler H hat nicht angeboten, ihn abzuholen. V verlangt sofort ihr Geld zurück.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 5, "o": [["H muss sofort zahlen, weil der Widerruf den Vertrag rückwirkend beseitigt.", "Falsch. § 357 IV gibt H ein Zurückbehaltungsrecht."], ["H muss erst zahlen, wenn er den Mixer geprüft hat.", "Falsch. Nachweis der Absendung genügt."], ["H darf die Hinsendekosten einbehalten.", "Falsch. Die Standard-Hinsendekosten sind zu erstatten."], ["H darf statt Geld einen Gutschein ausstellen.", "Falsch. Er muss dasselbe Zahlungsmittel verwenden."], ["H muss erst nach 30 Tagen zahlen.", "Falsch. Die Frist beträgt 14 Tage (§ 357 I)."], ["H darf die Rückzahlung verweigern, bis er den Mixer oder einen Absendenachweis hat.", "Richtig. Zurückbehaltungsrecht beim Verbrauchsgüterkauf. (§ 357 IV)"]], "id": "P2-frist-8"}, {"topic": "agb", "sv": "Musikfan M kauft am 1. 3. auf der Website des Veranstalters ein Ticket für ein Konzert am 20. 6. Eine Woche später will er den Kauf widerrufen.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 4, "o": [["M kann widerrufen, weil es ein Fernabsatzvertrag ist.", "Falsch. § 312g II Nr. 9 schließt das Widerrufsrecht aus."], ["M kann widerrufen, weil das Konzert erst in mehr als 14 Tagen stattfindet.", "Falsch. Auf den zeitlichen Abstand kommt es nicht an."], ["M kann nur widerrufen, wenn der Veranstalter zustimmt.", "Falsch. Das wäre kein Widerruf, sondern eine Vertragsaufhebung."], ["M kann nicht widerrufen, weil Tickets digitale Inhalte sind.", "Falsch. Der Grund ist die Freizeitbetätigung mit Termin."], ["Nein, weil es eine Freizeitveranstaltung mit festem Termin ist.", "Richtig. Ausnahme für terminierte Freizeitbetätigungen. (§ 312g II Nr. 9)"], ["M kann nicht widerrufen, weil das Ticket weniger als 40 € kostet.", "Falsch. Eine Wertgrenze gibt es hier nicht."]], "id": "P2-frist-9"}, {"topic": "frist", "sv": "Gläubiger G setzt Schuldner S am Samstag, 31. 1. 2026, eine Frist von „einem Monat“ zur Zahlung. Das Schreiben geht S am selben Tag zu.", "q": "Wann endet die Frist?", "c": 1, "o": [["Am Samstag, 28. 2. 2026, weil der Februar keinen 31. hat.", "Falsch. § 188 III führt zum 28. 2.; der ist aber ein Samstag (§ 193)."], ["Am Montag, 2. 3. 2026, weil der 28. 2. ein Samstag ist (§§ 188 III, 193).", "Richtig. Ende 28. 2. (Samstag) → nächster Werktag."], ["Am Sonntag, 1. 3. 2026, weil der Monat auf den Folgetag übergreift.", "Falsch. Bei fehlendem Tag endet die Frist am letzten Monatstag."], ["Am Dienstag, 3. 3. 2026, weil ein Monat immer 30 Tage hat.", "Falsch. Monatsfristen werden nach dem Kalender berechnet."], ["Am Samstag, 28. 2. 2026, 24 Uhr, weil § 193 nur Sonn- und Feiertage erfasst.", "Falsch. § 193 erfasst ausdrücklich auch den Sonnabend."], ["Am Freitag, 27. 2. 2026, weil die Frist vor dem Wochenende endet.", "Falsch. § 193 verschiebt nach hinten, nicht nach vorn."]], "id": "P2-frist-10"}, {"topic": "frist", "sv": "Vermieterin V mahnt Mieter M und setzt ihm „eine Woche“ Frist. Das Schreiben geht M am Mittwoch, 4. 11. 2026, zu.", "q": "Wann endet die Frist?", "c": 2, "o": [["Am Dienstag, 10. 11. 2026, weil der Zugangstag mitgezählt wird.", "Falsch. Der Ereignistag zählt nicht mit (§ 187 I)."], ["Am Donnerstag, 12. 11. 2026, weil die Frist erst am Folgetag beginnt und dann sieben volle Tage läuft.", "Falsch. Der Beginn am 5. 11. stimmt, sieben Tage enden aber am 11. 11."], ["Am Mittwoch, 11. 11. 2026, um 24 Uhr (§§ 187 I, 188 II).", "Richtig. Gleicher Wochentag in der Folgewoche."], ["Am Freitag, 13. 11. 2026, weil nur Werktage gezählt werden.", "Falsch. Es werden alle Kalendertage gezählt."], ["Am Mittwoch, 11. 11. 2026, um 12 Uhr, weil Fristen zur Tagesmitte enden.", "Falsch. Sie enden mit Ablauf des Tages."], ["Am Montag, 16. 11. 2026, weil eine Woche fünf Werktage hat.", "Falsch. Kalenderwoche, nicht Arbeitswoche."]], "id": "P2-frist-11"}, {"topic": "frist", "sv": "Verbraucher K kauft bei Händler H ein Fahrrad; es wird am 10. 3. 2024 übergeben. Am 2. 3. 2026 zeigt sich ein Defekt an der Schaltung. K verlangt Nacherfüllung; H bestreitet, dass der Mangel schon bei Übergabe vorlag.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 0, "o": [["Nicht verjährt; K muss aber beweisen, dass der Mangel schon bei Übergabe vorlag.", "Richtig. Verjährung erst am 10. 3. 2026; Vermutung abgelaufen."], ["Der Anspruch ist verjährt, weil die Gewährleistung beim Verbrauchsgüterkauf ein Jahr beträgt.", "Falsch. Die Verjährung beträgt zwei Jahre (§ 438 I Nr. 3)."], ["Der Anspruch ist nicht verjährt; die Beweislast trägt H, weil K Verbraucher ist.", "Falsch. Die Vermutung des § 477 I gilt nur für ein Jahr."], ["Der Anspruch ist verjährt, weil die Verjährung am Jahresende beginnt.", "Falsch. § 438 II: Beginn mit Ablieferung."], ["Der Anspruch ist nicht verjährt, weil die Verjährung erst mit Entdecken des Mangels beginnt.", "Falsch. Sie beginnt mit Ablieferung."], ["Der Anspruch ist nicht verjährt, weil die regelmäßige Verjährung drei Jahre beträgt.", "Falsch. Für Mängel gilt § 438."]], "id": "P2-frist-12"}, {"topic": "frist", "sv": "Handwerker H hat seit dem 20. 5. 2023 eine fällige Werklohnforderung gegen Kunde K; er kennt K und die Forderung. K zahlt nicht. Am 15. 11. 2026 reicht H Klage ein.", "q": "Welche der nachfolgenden Aussagen ist richtig?", "c": 3, "o": [["Die Forderung ist verjährt, weil seit dem 20. 5. 2023 mehr als drei Jahre vergangen sind.", "Falsch. Die Frist beginnt erst am Jahresende."], ["Die Forderung ist verjährt, weil Werklohn in zwei Jahren verjährt.", "Falsch. Es gilt die regelmäßige Verjährung."], ["Die Forderung verjährt erst nach 30 Jahren, weil sie fällig ist.", "Falsch. 30 Jahre gelten nur für Sonderfälle (§ 197)."], ["Die Forderung ist nicht verjährt; die Frist endet erst am 31. 12. 2026 (§§ 195, 199 I).", "Richtig. Drei Jahre ab Schluss des Jahres 2023."], ["Die Forderung ist nicht verjährt, weil die Verjährung erst mit einer Mahnung beginnt.", "Falsch. Die Mahnung hat keinen Einfluss auf den Beginn."], ["Die Forderung ist verjährt, weil die Verjährungsfrist am 20. 5. 2026 abgelaufen ist.", "Falsch. Der Beginn ist der 31. 12. 2023, 24 Uhr."]], "id": "P2-frist-13"}];
L.forEach(q=>{ if(!W.some(x=>x.id===q.id)) W.push(q); });
window.dispatchEvent(new Event('wpr-data'));
})();
